<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{ComplianceCase,User};final class ComplianceCasePolicy{public function viewAny(User$u):bool{/* UI audit 2026-09-27: was any active member */return$u->memberships()->where('status','ACTIVE')->exists()&&($u->hasPermission('compliance.cases.read'));}public function view(User$u,ComplianceCase$x):bool{return$x->tenant_id===app(TenantContext::class)->id()&&$this->viewAny($u);}public function update(User$u,ComplianceCase$x):bool{return$this->view($u,$x)&&$u->memberships()->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','COMPLIANCE_ADMIN'])->exists();}}
